using YunXiaoJob.Application.DTOs.Responses;
using YunXiaoJob.Application.Interfaces.Repositories;
using YunXiaoJob.Domain.Enums;
namespace YunXiaoJob.Application.UseCases.Queries;
public class GetCompanyJobPostingsUseCase { private readonly ICompanyRepository _companies; private readonly IJobPostingRepository _jobs; public GetCompanyJobPostingsUseCase(ICompanyRepository companies, IJobPostingRepository jobs) { _companies = companies; _jobs = jobs; } public async Task<IReadOnlyList<JobPostingResponse>> ExecuteAsync(Guid companyId, Guid uid, CancellationToken ct = default) { var member = await _companies.GetMemberAsync(companyId, uid, ct); if (member is null || !member.IsActive) throw new UnauthorizedAccessException(); return (await _jobs.GetByCompanyAsync(companyId, ct)).Select(x => new JobPostingResponse(x.Id,x.CompanyId,x.CreatedByMemberId,x.AssignedRecruiterMemberId,x.Title,x.Description,x.Requirements,x.Benefits,x.Location,x.EmploymentType,x.WorkplaceType,x.MinSalary,x.MaxSalary,x.Currency,x.ApplicationDeadline,x.Status,x.PublishedAtUtc,x.Skills.Select(s=>s.Name).ToList())).ToList(); } }
public class GetJobApplicationsUseCase { private readonly ICompanyRepository _companies; private readonly IJobPostingRepository _jobs; private readonly IJobApplicationRepository _applications; public GetJobApplicationsUseCase(ICompanyRepository companies,IJobPostingRepository jobs,IJobApplicationRepository applications) { _companies=companies;_jobs=jobs;_applications=applications; } public async Task<IReadOnlyList<JobApplicationResponse>> ExecuteAsync(Guid jobId, ApplicationStatus? status, Guid uid, CancellationToken ct=default) { var job=await _jobs.GetByIdAsync(jobId,cancellationToken:ct)??throw new KeyNotFoundException(); var member=await _companies.GetMemberAsync(job.CompanyId,uid,ct); if(member is null||!member.IsActive)throw new UnauthorizedAccessException(); var values=await _applications.GetByJobPostingAsync(jobId,status,ct); if(member.Role==CompanyMemberRole.Recruiter) values=values.Where(x=>x.AssignedRecruiterMemberId==member.Id).ToList(); return values.Select(x=>new JobApplicationResponse(x.Id,x.JobPostingId,x.CandidateProfileId,x.ResumeId,x.AssignedRecruiterMemberId,x.CoverLetter,x.Status,x.SubmittedAtUtc)).ToList(); } }
public class GetMyApplicationsUseCase { private readonly ICandidateRepository _candidates; private readonly IJobApplicationRepository _applications; public GetMyApplicationsUseCase(ICandidateRepository candidates,IJobApplicationRepository applications){_candidates=candidates;_applications=applications;} public async Task<IReadOnlyList<JobApplicationResponse>> ExecuteAsync(Guid uid,CancellationToken ct=default){var profile=await _candidates.GetProfileByUserIdAsync(uid,cancellationToken:ct)??throw new KeyNotFoundException();return (await _applications.GetByCandidateAsync(profile.Id,ct)).Select(x=>new JobApplicationResponse(x.Id,x.JobPostingId,x.CandidateProfileId,x.ResumeId,x.AssignedRecruiterMemberId,x.CoverLetter,x.Status,x.SubmittedAtUtc)).ToList();} }
